add('reimbursement','Payment and Cover','Pay and claim back','Receipt and insurer-claim route with no guarantee of reimbursement.',()=>back('insurance')+title('Pay and claim back','You pay for the service and submit a claim to your provider.')+list(['Check your plan’s eligibility, limits and exclusions first','Obtain authorisation if your provider requires it','Pay the agreed service fee','Request an itemised receipt and submit it to your provider'])+note('Your insurer or cash-plan provider decides whether to reimburse you. LifeCome Health cannot guarantee payment.')+btn('View receipt','test-receipt')+btn('Ask about reimbursement','insurance-support','secondary'),'insurance');
add('test-receipt','Payment and Cover','Test receipt','Invoice.',()=>back('reimbursement')+title('Receipt','Test appointment')+details([['Patient','Alex Taylor'],['Service',testName()],['Fee','Not quoted'],['Payment','No payment collected']])+downloadBtn(),'reimbursement');
// Shared entry points remain available while clinical testing has its own routes.
const originalResults=LC.screens['test-results']?.render;
LC.screens.messages.render=()=>title('Your messages','Stay connected with your teams.')+row('gp','GP care team','Consultation support','message-thread')+row('clinic','Tests & results team','Questions about checks and results','test-followup')+row('care','Care coordination','Assessment and ongoing care','care-message')+row('wellbeing','Wellbeing team','Support with your sessions','wellbeing-message')+row('card','Payment and cover support','Funding and eligibility enquiries','insurance-support')+note('Messages are not monitored for emergencies.');
// Reassign sequential display IDs after retiring eight sales pages.
LC.order.forEach((k,i)=>LC.screens[k].id=String(i+1).padStart(3,'0'));

const legacyResults=LC.screens.results; if(legacyResults){const old=legacyResults.render;legacyResults.render=()=>row('clinic','Tests and Health Checks results','Reviewed reports and next steps','test-results')+old();}
